import { node, field, input, select, button } from './ui.mjs';
import { queryProducts, queryOrders } from './query.mjs';
import { createLatestQueryRunner } from './latest-query.mjs';
import {
  PRODUCT_KEYS,
  ORDER_KEYS,
  ALL_FILTER_KEYS,
  productDefaults,
  orderDefaults,
  parseProductFilters,
  serializeProductFilters,
  parseOrderFilters,
  serializeOrderFilters,
  validateDateRange,
} from './filter-state.mjs';

const app = document.querySelector('#app');
let restorePageFromUrl = () => {};

renderApp();
window.addEventListener('popstate', () => restorePageFromUrl());

function renderApp() {
  const page = new URL(location.href).searchParams.get('page') === 'orders' ? 'orders' : 'products';
  const nav = node('nav');
  nav.setAttribute('aria-label', 'Pages');

  for (const [name, target] of [['Products', 'products'], ['Orders', 'orders']]) {
    const link = node('a', name);
    link.href = pageHref(target);
    if (target === page) link.setAttribute('aria-current', 'page');
    nav.append(link);
  }

  const pageRoot = node('section');
  app.replaceChildren(nav, pageRoot);
  restorePageFromUrl = page === 'orders'
    ? setupOrdersPage(pageRoot)
    : setupProductsPage(pageRoot);
  restorePageFromUrl();
}

function setupProductsPage(root) {
  const heading = node('h1', 'Products');
  const form = node('form');
  const keyword = input();
  const category = select([
    ['', 'All categories'],
    ['wear', 'Wear'],
    ['food', 'Food'],
    ['home', 'Home'],
  ]);
  const status = select([
    ['published', 'Published'],
    ['draft', 'Draft'],
    ['', 'All statuses'],
  ]);
  const results = createResultsView();
  const runQuery = createLatestQueryRunner(queryProducts, results);

  form.append(
    field('Product keyword', keyword),
    field('Product category', category),
    field('Product status', status),
    button('Apply', undefined, 'submit'),
    button('Reset', () => {
      setProductDraft(productDefaults);
      applyProductDraft();
    }),
  );
  form.addEventListener('submit', event => {
    event.preventDefault();
    applyProductDraft();
  });

  root.append(heading, form, results.element);

  function setProductDraft(filters) {
    keyword.value = filters.q;
    category.value = filters.category;
    status.value = filters.status;
  }

  function readProductDraft() {
    return { q: keyword.value, category: category.value, status: status.value };
  }

  function applyProductDraft() {
    const filters = readProductDraft();
    pushFilters(PRODUCT_KEYS, serializeProductFilters(filters));
    runQuery(filters);
  }

  return () => {
    const filters = parseProductFilters(new URL(location.href).searchParams);
    setProductDraft(filters);
    runQuery(filters);
  };
}

function setupOrdersPage(root) {
  const heading = node('h1', 'Orders');
  const form = node('form');
  const keyword = input();
  const from = input('date');
  const to = input('date');
  const status = select([
    ['', 'All statuses'],
    ['new', 'New'],
    ['paid', 'Paid'],
  ]);
  const dateError = node('p');
  dateError.id = 'order-date-error';
  dateError.className = 'field-error';
  dateError.setAttribute('role', 'alert');
  dateError.hidden = true;
  const results = createResultsView();
  const runQuery = createLatestQueryRunner(queryOrders, results);

  from.setAttribute('aria-describedby', dateError.id);
  to.setAttribute('aria-describedby', dateError.id);
  form.append(
    field('Order keyword', keyword),
    field('From date', from),
    field('To date', to),
    field('Order status', status),
    button('Reset', () => {
      setOrderDraft(orderDefaults);
      publishOrderDraft();
    }),
    dateError,
  );
  form.addEventListener('submit', event => event.preventDefault());
  keyword.addEventListener('input', publishOrderDraft);
  from.addEventListener('input', publishOrderDraft);
  to.addEventListener('input', publishOrderDraft);
  status.addEventListener('change', publishOrderDraft);

  root.append(heading, form, results.element);

  function setOrderDraft(filters) {
    keyword.value = filters.q;
    from.value = filters.from;
    to.value = filters.to;
    status.value = filters.status;
    showDateError('');
  }

  function readOrderDraft() {
    return { q: keyword.value, from: from.value, to: to.value, status: status.value };
  }

  function publishOrderDraft() {
    const filters = readOrderDraft();
    const error = validateDateRange(filters.from, filters.to);
    showDateError(error);
    if (error) return;

    pushFilters(ORDER_KEYS, serializeOrderFilters(filters));
    runQuery(filters);
  }

  function showDateError(message) {
    dateError.textContent = message;
    dateError.hidden = !message;
    from.setAttribute('aria-invalid', String(Boolean(message)));
    to.setAttribute('aria-invalid', String(Boolean(message)));
  }

  return () => {
    const filters = parseOrderFilters(new URL(location.href).searchParams);
    setOrderDraft(filters);
    runQuery(filters);
  };
}

function createResultsView() {
  const element = node('section');
  element.className = 'results';
  const count = node('p', 'Loading results…');
  count.setAttribute('role', 'status');
  const error = node('p');
  error.className = 'query-error';
  error.setAttribute('role', 'alert');
  error.hidden = true;
  const list = node('ul');
  list.setAttribute('aria-label', 'Results');
  element.append(count, error, list);

  return {
    element,
    start() {
      list.setAttribute('aria-busy', 'true');
      error.hidden = true;
      error.textContent = '';
    },
    succeed(result) {
      list.replaceChildren(...result.rows.map(row => node('li', row.name)));
      count.textContent = `${result.count} results`;
      error.hidden = true;
      error.textContent = '';
    },
    fail(reason) {
      error.textContent = reason instanceof Error ? reason.message : 'Query failed';
      error.hidden = false;
    },
    finish() {
      list.removeAttribute('aria-busy');
    },
  };
}

function pushFilters(ownedKeys, values) {
  const url = new URL(location.href);
  for (const key of ownedKeys) url.searchParams.delete(key);
  for (const [key, value] of values) {
    if (value !== null) url.searchParams.set(key, value);
  }
  history.pushState(null, '', url);
}

function pageHref(page) {
  const url = new URL(location.href);
  url.searchParams.set('page', page);
  for (const key of ALL_FILTER_KEYS) url.searchParams.delete(key);
  return `${url.pathname}?${url.searchParams}`;
}

import { today } from './data.mjs';

export const PRODUCT_KEYS = ['p_q', 'p_category', 'p_status'];
export const ORDER_KEYS = ['o_q', 'o_from', 'o_to', 'o_status'];
export const ALL_FILTER_KEYS = [...PRODUCT_KEYS, ...ORDER_KEYS];

const PRODUCT_CATEGORIES = new Set(['wear', 'food', 'home']);
const PRODUCT_STATUSES = new Set(['', 'published', 'draft']);
const ORDER_STATUSES = new Set(['', 'new', 'paid']);

export const productDefaults = Object.freeze({ q: '', category: '', status: 'published' });
export const orderDefaults = Object.freeze({
  q: '',
  from: addUtcDays(today, -29),
  to: today,
  status: '',
});

export function parseProductFilters(params) {
  const category = params.get('p_category') ?? productDefaults.category;
  const status = params.has('p_status') ? params.get('p_status') : productDefaults.status;
  return {
    q: params.get('p_q') ?? productDefaults.q,
    category: PRODUCT_CATEGORIES.has(category) ? category : productDefaults.category,
    status: PRODUCT_STATUSES.has(status) ? status : productDefaults.status,
  };
}

export function serializeProductFilters(filters) {
  return new Map([
    ['p_q', filters.q || null],
    ['p_category', filters.category || null],
    ['p_status', filters.status === productDefaults.status ? null : filters.status],
  ]);
}

export function parseOrderFilters(params) {
  const from = params.get('o_from');
  const to = params.get('o_to');
  const status = params.get('o_status') ?? orderDefaults.status;
  const rangeIsValid = !validateDateRange(from, to);
  return {
    q: params.get('o_q') ?? orderDefaults.q,
    from: rangeIsValid ? from : orderDefaults.from,
    to: rangeIsValid ? to : orderDefaults.to,
    status: ORDER_STATUSES.has(status) ? status : orderDefaults.status,
  };
}

export function serializeOrderFilters(filters) {
  return new Map([
    ['o_q', filters.q || null],
    ['o_from', filters.from === orderDefaults.from ? null : filters.from],
    ['o_to', filters.to === orderDefaults.to ? null : filters.to],
    ['o_status', filters.status || null],
  ]);
}

export function validateDateRange(from, to) {
  if (!isIsoDate(from) || !isIsoDate(to)) return 'Enter a complete valid date range.';
  if (from > to) return 'From date must be before or equal to To date.';
  return '';
}

function isIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value ?? '')) return false;
  const date = new Date(`${value}T00:00:00Z`);
  return !Number.isNaN(date.valueOf()) && date.toISOString().slice(0, 10) === value;
}

function addUtcDays(value, days) {
  const date = new Date(`${value}T00:00:00Z`);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

export function node(tag, text) { const el=document.createElement(tag); if(text!==undefined)el.textContent=text; return el; }
export function input(type='text') { const el=node('input'); el.type=type; return el; }
export function select(options) { const el=node('select'); for(const [value,label] of options){const option=node('option',label);option.value=value;el.append(option);}return el; }
export function field(label, control) { const el=node('label'); const text=node('span',label);el.append(text,control);return el; }
export function button(label, action, type='button') { const el=node('button',label);el.type=type;if(action)el.addEventListener('click',action);return el; }

